from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def splitBST(self, root: Optional[TreeNode], target: int) -> List[Optional[TreeNode]]:
        if not root:
            return [None, None]
        if root.val <= target:
            left, right = self.splitBST(root.right, target)
            root.right = left
            return [root, right]
        else:
            left, right = self.splitBST(root.left, target)
            root.left = right
            return [left, root]

class Solution {
public:
    vector<TreeNode*> splitBST(TreeNode* root, int target) {
        if (!root) return {nullptr, nullptr};
        if (root->val <= target) {
            auto res = splitBST(root->right, target);
            root->right = res[0];
            return {root, res[1]};
        } else {
            auto res = splitBST(root->left, target);
            root->left = res[1];
            return {res[0], root};
        }
    }
};

class Solution {
    public TreeNode[] splitBST(TreeNode root, int target) {
        if (root == null) return new TreeNode[]{null, null};
        if (root.val <= target) {
            TreeNode[] res = splitBST(root.right, target);
            root.right = res[0];
            return new TreeNode[]{root, res[1]};
        } else {
            TreeNode[] res = splitBST(root.left, target);
            root.left = res[1];
            return new TreeNode[]{res[0], root};
        }
    }
}

var splitBST = function(root, target) {
    if (!root) return [null, null];
    if (root.val <= target) {
        const [left, right] = splitBST(root.right, target);
        root.right = left;
        return [root, right];
    } else {
        const [left, right] = splitBST(root.left, target);
        root.left = right;
        return [left, root];
    }
};
